const INFO_REVERSE_LOOKUP: Record<string, { lang: string; page: InfoPageType }> = {};

Object.entries(INFO_SLUG_MAP).forEach(([lang, pages]) => {
  Object.entries(pages).forEach(([page, slug]) => {
    INFO_REVERSE_LOOKUP[slug] = { lang, page: page as InfoPageType };
  });
});

export function getInfoPageFromSlug(slug: string): InfoPageType | null {
  if (INFO_REVERSE_LOOKUP[slug]) {
    return INFO_REVERSE_LOOKUP[slug].page;
  }
  
  // Fallback to EN slugs
  if (Object.values(INFO_FALLBACK_SLUGS).includes(slug)) {
    return slug as InfoPageType;
  }
  
  return null;
}

export function getLocalizedInfoSlug(page: InfoPageType, lang: string): string {
  if (INFO_SLUG_MAP[lang] && INFO_SLUG_MAP[lang][page]) {
    return INFO_SLUG_MAP[lang][page];
  }
  return INFO_FALLBACK_SLUGS[page];
}
